import{A as e,H as t,P as n,_ as r,a as i,f as a,g as o,h as s,t as c,u as l}from"./chunks/plugin-vue_export-helper.I53torQa.js";var u=JSON.parse(`{"title":"昇腾硬件技术介绍：以 910C 为主，兼述 950 系列","description":"","frontmatter":{},"headers":[],"relativePath":"ascend/architecture/昇腾硬件技术介绍：以 910C 为主，兼述 950 系列.md","filePath":"ascend/architecture/昇腾硬件技术介绍：以 910C 为主，兼述 950 系列.md","lastUpdated":1795411813000}`),d={name:`ascend/architecture/昇腾硬件技术介绍：以 910C 为主，兼述 950 系列.md`};function f(c,u,d,f,p,m){let h=n(`Mermaid`);return e(),a(`div`,null,[u[4]||=s(`<h1 id="昇腾硬件技术介绍-以-910c-为主-兼述-950-系列" tabindex="-1">昇腾硬件技术介绍：以 910C 为主，兼述 950 系列 <a class="header-anchor" href="#昇腾硬件技术介绍-以-910c-为主-兼述-950-系列" aria-label="Permalink to “昇腾硬件技术介绍：以 910C 为主，兼述 950 系列”">​</a></h1><blockquote><p>资料核对日期：2026 年 11 月 23 日。适用于硬件调研、技术交流和方案初选；采购与验收以对应型号、物料配置及合同技术附件为准。</p></blockquote><p>昇腾 910C 是 Atlas A3 平台的核心 AI 加速器之一。理解这套平台，需要同时看三个层面：NPU 如何计算和访问内存，单台服务器如何组织 CPU 与 NPU，以及多台服务器如何通过灵衢互联形成超节点。950 系列延续超节点架构，但进一步引入原生低精度计算，并以 950PR 和 950DT 区分偏重吞吐与偏重访存的应用。<a href="https://www.huawei.com/cn/news/2025/9/hc-xu-keynote-speech" target="_blank" rel="noreferrer">华为全联接大会技术演讲</a>、<a href="https://hifloat.gccorg.com/pdf/%E6%98%87%E8%85%BE950%20NPU%E6%9E%B6%E6%9E%84%E7%99%BD%E7%9A%AE%E4%B9%A6.pdf" target="_blank" rel="noreferrer">昇腾 950 NPU 架构白皮书（镜像）</a></p><h2 id="产品层级与命名" tabindex="-1">产品层级与命名 <a class="header-anchor" href="#产品层级与命名" aria-label="Permalink to “产品层级与命名”">​</a></h2><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>层级</th><th>代表名称</th><th>含义</th></tr></thead><tbody><tr><td>处理器</td><td>昇腾 910C、昇腾 950PR、昇腾 950DT</td><td>AI 加速器的芯片型号。一个封装可包含多个裸片（Die）；不能按裸片数计算物理 NPU 数量。<a href="https://arxiv.org/html/2506.12708" target="_blank" rel="noreferrer">CloudMatrix384 架构论文 §3.2</a>、<a href="https://hifloat.gccorg.com/pdf/%E6%98%87%E8%85%BE950%20NPU%E6%9E%B6%E6%9E%84%E7%99%BD%E7%9A%AE%E4%B9%A6.pdf" target="_blank" rel="noreferrer">昇腾 950 NPU 架构白皮书 §3</a></td></tr><tr><td>加速卡／服务器</td><td>Atlas 350、Atlas 800T A3、Atlas 800I A3</td><td>Atlas 350 是搭载 950PR 的 PCIe 加速卡；800T A3、800I A3 分别是面向训练与推理的 8 NPU 服务器，不是芯片型号。<a href="https://www.hiascend.com/hardware/accelerator-card" target="_blank" rel="noreferrer">Atlas 350</a>、<a href="https://e.huawei.com/cn/products/computing/ascend/atlas-800t-a3" target="_blank" rel="noreferrer">Atlas 800T A3</a>、<a href="https://e.huawei.com/cn/products/computing/ascend/atlas-800i-a3" target="_blank" rel="noreferrer">Atlas 800I A3</a></td></tr><tr><td>超节点</td><td>Atlas 900 A3 SuperPoD、Atlas 950 SuperPoD</td><td>使用高速互联组织多节点，使跨服务器的设备通信和远端内存访问不再局限于普通主机网络；这不意味着设备共享一块物理内存。<a href="https://e.huawei.com/cn/products/computing/ascend/atlas-900-a3-superpod" target="_blank" rel="noreferrer">Atlas 900 A3</a>、<a href="https://www.hiascend.com/hardware/cluster?tag=950" target="_blank" rel="noreferrer">Atlas 950 SuperPoD</a></td></tr><tr><td>云服务实例</td><td>CloudMatrix384</td><td>华为云基于 Atlas 900 超节点构建的云服务实例，不是 910C 的别名，也不是另一款芯片。<a href="https://www.huawei.com/cn/news/2025/9/hc-xu-keynote-speech" target="_blank" rel="noreferrer">华为全联接大会技术演讲</a></td></tr></tbody></table></div><p>Atlas A3 产品页有时只写“昇腾 910”；华为发布资料明确将 Atlas 900 A3 所搭载的处理器称为昇腾 910C。开发文档对 Atlas A3 系列给出的标识为 <code>NPU_ARCH=2201</code>、<code>soc_version=Ascend910_93xx</code>；具体后缀应在目标设备上查询，不宜仅凭商品名称硬编码。<a href="https://www.huawei.com/en/news/2025/9/hc-xu-keynote-speech" target="_blank" rel="noreferrer">华为全联接大会技术演讲</a>、<a href="https://www.hiascend.com/document/detail/zh/Glossary/productform/hardwaredesc_0001.html" target="_blank" rel="noreferrer">昇腾产品形态说明</a></p><h2 id="昇腾-910c-封装、计算与内存" tabindex="-1">昇腾 910C：封装、计算与内存 <a class="header-anchor" href="#昇腾-910c-封装、计算与内存" aria-label="Permalink to “昇腾 910C：封装、计算与内存”">​</a></h2><h3 id="双裸片封装" tabindex="-1">双裸片封装 <a class="header-anchor" href="#双裸片封装" aria-label="Permalink to “双裸片封装”">​</a></h3><p>CloudMatrix384 架构论文将其处理器简称为“Ascend 910”，并描述了双计算裸片、封装内高速互联和 8 个高带宽内存堆栈。论文所述配置中，每个计算裸片有 24 个矩阵核心（AIC）和 48 个向量核心（AIV）；核心数对应论文所述配置，不应推定所有商业型号完全一致。<a href="https://arxiv.org/html/2506.12708" target="_blank" rel="noreferrer">CloudMatrix384 架构论文 §3.2</a>、<a href="https://www.huawei.com/en/news/2025/9/hc-xu-keynote-speech" target="_blank" rel="noreferrer">华为对 910C 的产品命名</a></p>`,9),(e(),l(i,null,{default:t(()=>[r(h,{id:`mermaid-87`,class:`mermaid`,graph:`flowchart%20TB%0A%20%20%20%20subgraph%20P%5B%22%E4%B8%80%E4%B8%AA%20910C%20NPU%20%E5%B0%81%E8%A3%85%22%5D%0A%20%20%20%20%20%20%20%20H%5B%22%E5%B0%81%E8%A3%85%E5%86%85%E9%AB%98%E5%B8%A6%E5%AE%BD%E5%86%85%E5%AD%98%20%C2%B7%20%E5%85%B1%208%20%E4%B8%AA%E5%A0%86%E6%A0%88%22%5D%0A%20%20%20%20%20%20%20%20D0%5B%22%E8%AE%A1%E7%AE%97%E8%A3%B8%E7%89%87%200%20%C2%B7%20AIC%20%2F%20AIV%22%5D%0A%20%20%20%20%20%20%20%20D1%5B%22%E8%AE%A1%E7%AE%97%E8%A3%B8%E7%89%87%201%20%C2%B7%20AIC%20%2F%20AIV%22%5D%0A%20%20%20%20%20%20%20%20D0%20---%7C%22%E5%B0%81%E8%A3%85%E5%86%85%E9%AB%98%E9%80%9F%E4%BA%92%E8%81%94%22%7C%20D1%0A%20%20%20%20%20%20%20%20H%20---%20D0%0A%20%20%20%20%20%20%20%20H%20---%20D1%0A%20%20%20%20end%0A%20%20%20%20P%20---%20U%5B%22%E7%81%B5%E8%A1%A2%E4%BA%92%E8%81%94%E5%B9%B3%E9%9D%A2%20%C2%B7%20%E8%B6%85%E8%8A%82%E7%82%B9%E5%86%85%22%5D%0A%20%20%20%20P%20---%20R%5B%22RoCE%20%E7%BD%91%E7%BB%9C%E5%B9%B3%E9%9D%A2%20%C2%B7%20%E8%B7%A8%E8%B6%85%E8%8A%82%E7%82%B9%22%5D%0A`})]),fallback:t(()=>[...u[0]||=[o(` Loading... `,-1)]]),_:1})),u[5]||=s(`<p>图 1：以 CloudMatrix384 所用处理器为例，展示封装和外部互联的逻辑关系；不表示 HBM 堆栈的物理排布或端口数量。封装内的裸片互联与超节点内的 NPU 互联是不同链路。<a href="https://arxiv.org/html/2506.12708" target="_blank" rel="noreferrer">CloudMatrix384 架构论文 §3</a></p><h3 id="计算单元与典型数据流" tabindex="-1">计算单元与典型数据流 <a class="header-anchor" href="#计算单元与典型数据流" aria-label="Permalink to “计算单元与典型数据流”">​</a></h3><ul><li><strong>Cube（矩阵单元）</strong>：用于矩阵乘法等规则、可分块的密集计算，例如 Transformer 中的线性层。分块数据从全局内存（GM）进入核内缓冲区，矩阵结果可经 FixPipe 写回 GM。<a href="https://www.hiascend.com/document/detail/zh/canncommercial/850/opdevg/Ascendcopdevg/atlas_ascendc_10_0008.html" target="_blank" rel="noreferrer">昇腾 Ascend C 硬件架构</a></li><li><strong>Vector（向量单元）与 Scalar（标量单元）</strong>：Vector 处理逐元素运算、归约等任务，Scalar 负责地址计算、循环等控制工作；MTE（内存搬运引擎）负责不同层级间的数据搬运。<a href="https://www.hiascend.com/document/detail/zh/canncommercial/850/opdevg/Ascendcopdevg/atlas_ascendc_10_0008.html" target="_blank" rel="noreferrer">昇腾 Ascend C 硬件架构</a></li></ul>`,3),(e(),l(i,null,{default:t(()=>[r(h,{id:`mermaid-106`,class:`mermaid`,graph:`flowchart%20LR%0A%20%20%20%20G0%5B%22GM%EF%BC%9A%E8%BE%93%E5%85%A5%22%5D%20--%3E%7C%22MTE2%22%7C%20L1%5B%22L1%20%E7%BC%93%E5%86%B2%22%5D%0A%20%20%20%20L1%20--%3E%7C%22MTE1%22%7C%20L0%5B%22L0A%20%2F%20L0B%22%5D%20--%3E%20C%5B%22Cube%22%5D%20--%3E%20L0C%5B%22L0C%22%5D%0A%20%20%20%20L0C%20--%3E%7C%22FixPipe%22%7C%20G1%5B%22GM%EF%BC%9A%E8%BE%93%E5%87%BA%22%5D%0A%20%20%20%20G0%20--%3E%7C%22MTE2%22%7C%20B0%5B%22%E6%A0%B8%E5%86%85%E7%BB%9F%E4%B8%80%E7%BC%93%E5%86%B2%22%5D%20--%3E%20V%5B%22Vector%22%5D%20--%3E%20B1%5B%22%E6%A0%B8%E5%86%85%E7%BB%9F%E4%B8%80%E7%BC%93%E5%86%B2%22%5D%0A%20%20%20%20B1%20--%3E%7C%22MTE3%22%7C%20G1%0A`})]),fallback:t(()=>[...u[1]||=[o(` Loading... `,-1)]]),_:1})),u[6]||=s(`<p>图 2：矩阵与向量计算的典型数据流。Ascend C 文档中的 <code>UB</code> 可指核内 Unified Buffer（统一缓冲区）；互联文档中的 <code>UB</code> 则指 UnifiedBus（灵衢总线），两者不是同一个概念。<a href="https://www.hiascend.com/document/detail/zh/canncommercial/850/opdevg/Ascendcopdevg/atlas_ascendc_10_0008.html" target="_blank" rel="noreferrer">Ascend C 硬件架构</a>、<a href="https://arxiv.org/html/2506.12708" target="_blank" rel="noreferrer">CloudMatrix384 架构论文 §3</a></p><h3 id="如何读-910c-的规格" tabindex="-1">如何读 910C 的规格 <a class="header-anchor" href="#如何读-910c-的规格" aria-label="Permalink to “如何读 910C 的规格”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>指标</th><th>公开值与适用范围</th></tr></thead><tbody><tr><td>设备内存</td><td>Atlas 800T A3、800I A3 产品页均列出每台 <strong>8 × 128 GB</strong>、设备内存带宽 <strong>3.2 TB/s</strong>；这是 NPU 内存口径，不是主机 DDR5 容量，也不是设备互联带宽。<a href="https://e.huawei.com/cn/products/computing/ascend/atlas-800t-a3" target="_blank" rel="noreferrer">Atlas 800T A3</a>、<a href="https://e.huawei.com/cn/products/computing/ascend/atlas-800i-a3" target="_blank" rel="noreferrer">Atlas 800I A3</a></td></tr><tr><td>FP16 峰值</td><td>华为云团队论文对所用 910C 给出每裸片约 400 TFLOPS，即双裸片封装约 <strong>800 TFLOPS</strong>；华为企业产品页则按整机配置给出峰值，例如 800T A3 为 6.0 PFLOPS，800I A3 为 4.48 PFLOPS。800 TFLOPS 不是所有 A3 整机所配 NPU 的通用承诺。<a href="https://arxiv.org/pdf/2501.14417v3" target="_blank" rel="noreferrer">DeepServe 论文</a>、<a href="https://e.huawei.com/cn/products/computing/ascend/atlas-800t-a3" target="_blank" rel="noreferrer">Atlas 800T A3</a>、<a href="https://e.huawei.com/cn/products/computing/ascend/atlas-800i-a3" target="_blank" rel="noreferrer">Atlas 800I A3</a></td></tr><tr><td>计算精度</td><td>CloudMatrix384 论文描述的计算引擎支持 FP16、BF16 和 INT8；950 原生低精度格式的产品规格不能套用到 910C。实际跑某个模型还须核对相应算子和软件版本。<a href="https://arxiv.org/html/2506.12708" target="_blank" rel="noreferrer">CloudMatrix384 架构论文 §3.2</a>、<a href="https://www.huawei.com/cn/news/2025/9/hc-xu-keynote-speech" target="_blank" rel="noreferrer">950 系列技术演讲</a></td></tr><tr><td>设备间互联</td><td>A3 产品页标称 D2D（Device-to-Device）互联带宽 <strong>双向 784 GB/s</strong>。它不是封装内两个裸片之间的链路速率，也不是任意一条 RoCE 链路的速率。<a href="https://e.huawei.com/cn/products/computing/ascend/atlas-900-a3-superpod" target="_blank" rel="noreferrer">Atlas 900 A3</a>、<a href="https://arxiv.org/html/2506.12708" target="_blank" rel="noreferrer">CloudMatrix384 架构论文 §3</a></td></tr><tr><td>功耗与散热</td><td>本文不以二手资料中的单芯片瓦数替代模组、整机或机柜功耗。机房设计应按目标配置核对最大输入功率、供电与冗余方式，再确定风冷或液冷能力。<a href="https://support.huawei.com/enterprise/en/ascend-computing/atlas-800t-a3-pid-261716443" target="_blank" rel="noreferrer">Atlas 800T A3 硬件支持文档</a>、<a href="https://e.huawei.com/cn/products/computing/ascend/atlas-900-a3-superpod" target="_blank" rel="noreferrer">Atlas 900 A3</a></td></tr></tbody></table></div><h2 id="atlas-a3-从单机到-384-卡超节点" tabindex="-1">Atlas A3：从单机到 384 卡超节点 <a class="header-anchor" href="#atlas-a3-从单机到-384-卡超节点" aria-label="Permalink to “Atlas A3：从单机到 384 卡超节点”">​</a></h2><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>产品</th><th>NPU 与主机</th><th>官方公开峰值</th><th>散热与典型用途</th></tr></thead><tbody><tr><td><a href="https://e.huawei.com/cn/products/computing/ascend/atlas-800t-a3" target="_blank" rel="noreferrer">Atlas 800T A3</a></td><td>10U；8 颗昇腾 NPU、4 颗鲲鹏 920；32 个 DDR5 内存插槽</td><td>6.0 PFLOPS FP16；12.0 POPS INT8</td><td>风冷；预训练、后训练</td></tr><tr><td><a href="https://e.huawei.com/cn/products/computing/ascend/atlas-800i-a3" target="_blank" rel="noreferrer">Atlas 800I A3</a></td><td>10U；8 颗昇腾 NPU、4 颗鲲鹏 920；32 个 DDR5 内存插槽</td><td>4.48 PFLOPS FP16；8.96 POPS INT8</td><td>风冷；大模型推理</td></tr><tr><td><a href="https://e.huawei.com/cn/products/computing/ascend/atlas-900-a3-superpod" target="_blank" rel="noreferrer">Atlas 900 A3 SuperPoD</a></td><td>最大 384 颗昇腾 NPU、192 颗鲲鹏 920；12 个计算柜、4 个总线设备柜</td><td>产品页列出 307.2 / 288.7 PFLOPS FP16 两档</td><td>计算柜液冷、总线设备柜风冷；规模化训推</td></tr></tbody></table></div><p>800T A3 和 800I A3 的产品页均列出 8 个用于 RoCE 的 400GE 接口、56 个用于总线协议的 400GE 接口；虽然都标作 400GE，所承载的通信平面不同，不能据此把两类端口合并为一个业务网络。Atlas 900 A3 产品页还列出 16、32、64、128、256、384 卡逻辑超节点配置；逻辑分组规模不同于实际安装的物理卡数。<a href="https://e.huawei.com/cn/products/computing/ascend/atlas-800t-a3" target="_blank" rel="noreferrer">Atlas 800T A3</a>、<a href="https://e.huawei.com/cn/products/computing/ascend/atlas-800i-a3" target="_blank" rel="noreferrer">Atlas 800I A3</a>、<a href="https://e.huawei.com/cn/products/computing/ascend/atlas-900-a3-superpod" target="_blank" rel="noreferrer">Atlas 900 A3</a></p><h3 id="互联拓扑与三个通信平面" tabindex="-1">互联拓扑与三个通信平面 <a class="header-anchor" href="#互联拓扑与三个通信平面" aria-label="Permalink to “互联拓扑与三个通信平面”">​</a></h3><p>CloudMatrix384 的公开实现由 48 台计算节点组成，每节点配置 8 颗 NPU、4 颗 CPU 和 7 颗板载灵衢交换芯片。节点内为第一级互联，通信柜内的第二级交换被划分为 7 个独立子平面，按无收敛设计连接各计算节点；这里的“无收敛”描述交换拓扑，不代表任意两个设备都能在满并发下独占全部标称带宽。<a href="https://arxiv.org/html/2506.12708" target="_blank" rel="noreferrer">CloudMatrix384 架构论文 §3.3–3.4</a></p>`,8),(e(),l(i,null,{default:t(()=>[r(h,{id:`mermaid-241`,class:`mermaid`,graph:`flowchart%20LR%0A%20%20%20%20subgraph%20POD%5B%22CloudMatrix384%20%E8%B6%85%E8%8A%82%E7%82%B9%20%C2%B7%20%E5%85%B1%2048%20%E4%B8%AA%E8%AE%A1%E7%AE%97%E8%8A%82%E7%82%B9%22%5D%0A%20%20%20%20%20%20%20%20A%5B%22%E8%AE%A1%E7%AE%97%E8%8A%82%E7%82%B9%20A%3Cbr%2F%3E8%20NPU%20%2B%204%20CPU%22%5D%20---%20LA%5B%22%E6%9D%BF%E8%BD%BD%E4%B8%80%E7%BA%A7%E7%81%B5%E8%A1%A2%E4%BA%A4%E6%8D%A2%22%5D%0A%20%20%20%20%20%20%20%20B%5B%22%E8%AE%A1%E7%AE%97%E8%8A%82%E7%82%B9%20B%3Cbr%2F%3E8%20NPU%20%2B%204%20CPU%22%5D%20---%20LB%5B%22%E6%9D%BF%E8%BD%BD%E4%B8%80%E7%BA%A7%E7%81%B5%E8%A1%A2%E4%BA%A4%E6%8D%A2%22%5D%0A%20%20%20%20%20%20%20%20LA%20---%20SW%5B%22%E9%80%9A%E4%BF%A1%E6%9F%9C%3Cbr%2F%3E%E4%BA%8C%E7%BA%A7%E7%81%B5%E8%A1%A2%E4%BA%A4%E6%8D%A2%20%C2%B7%207%20%E4%B8%AA%E5%AD%90%E5%B9%B3%E9%9D%A2%22%5D%0A%20%20%20%20%20%20%20%20LB%20---%20SW%0A%20%20%20%20end%0A%20%20%20%20A%20--%3E%7C%22NPU%EF%BC%9ARoCE%20%2F%20RDMA%22%7C%20EXT%5B%22%E5%85%B6%E4%BB%96%E8%B6%85%E8%8A%82%E7%82%B9%E6%88%96%20RDMA%20%E7%B3%BB%E7%BB%9F%22%5D%0A%20%20%20%20A%20--%3E%7C%22DPU%EF%BC%9AVPC%20%2F%20%E4%BB%A5%E5%A4%AA%E7%BD%91%22%7C%20DC%5B%22%E7%AE%A1%E7%90%86%E3%80%81%E4%B8%9A%E5%8A%A1%E6%8E%A5%E5%85%A5%E4%B8%8E%E6%8C%81%E4%B9%85%E5%8C%96%E5%AD%98%E5%82%A8%22%5D%0A`})]),fallback:t(()=>[...u[2]||=[o(` Loading... `,-1)]]),_:1})),u[7]||=s(`<p>图 3：CloudMatrix384 的三个互联平面，只画两个代表性计算节点，省略其余节点和冗余连接。论文的网络配图采用单向口径，不应直接与产品页的双向 D2D 数字相比。<a href="https://arxiv.org/html/2506.12708" target="_blank" rel="noreferrer">CloudMatrix384 架构论文 §3</a>、<a href="https://e.huawei.com/cn/products/computing/ascend/atlas-900-a3-superpod" target="_blank" rel="noreferrer">Atlas 900 A3</a></p><ul><li><strong>灵衢（Scale-up，域内扩展）</strong>：连接超节点内的 CPU 与 NPU，为细粒度通信和远端内存访问提供高速路径。统一编址让资源可寻址，但不保证远端访问与本地 HBM 具有同等性能，也不意味着框架会自动聚合全部内存。<a href="https://arxiv.org/html/2506.12708" target="_blank" rel="noreferrer">CloudMatrix384 架构论文 §3–4</a></li><li><strong>RoCE（Scale-out，域外扩展）</strong>：在 CloudMatrix384 所述实现中承载超节点间的 RDMA 通信，可用于跨域训练、推理及预填充和解码阶段之间的 KV 缓存传输。<a href="https://arxiv.org/html/2506.12708" target="_blank" rel="noreferrer">CloudMatrix384 架构论文 §3.1</a></li><li><strong>VPC（数据中心网络）</strong>：由擎天 DPU 接入，承载部署、监控、业务接入以及持久化存储访问；它与 NPU 的 RoCE 平面分开。<a href="https://arxiv.org/html/2506.12708" target="_blank" rel="noreferrer">CloudMatrix384 架构论文 §3.1</a></li></ul><h2 id="昇腾-950-同一代架构-两种内存配置方向" tabindex="-1">昇腾 950：同一代架构，两种内存配置方向 <a class="header-anchor" href="#昇腾-950-同一代架构-两种内存配置方向" aria-label="Permalink to “昇腾 950：同一代架构，两种内存配置方向”">​</a></h2><p>950PR 与 950DT 使用共同的第三代达芬奇架构，支持 SIMD（单指令多数据）与 SIMT（单指令多线程）混合编程，以及 FP8、MXFP8、HiF8、MXFP4 等低精度格式。白皮书描述两款芯片均含 2 个 AI Die 和 2 个 I/O Die，区别之一是封装内高带宽内存的配置。白皮书给出的灵衢 2.0 满端口理论峰值约为 <strong>2 TB/s 双向</strong>，不是各卡型、各组网方式均可达到的实测带宽。<a href="https://hifloat.gccorg.com/pdf/%E6%98%87%E8%85%BE950%20NPU%E6%9E%B6%E6%9E%84%E7%99%BD%E7%9A%AE%E4%B9%A6.pdf" target="_blank" rel="noreferrer">昇腾 950 NPU 架构白皮书 §3、§5</a></p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>指标</th><th>950PR</th><th>950DT</th></tr></thead><tbody><tr><td>主要场景</td><td>大模型预填充（Prefill）、推荐及多模态推理。<a href="https://hifloat.gccorg.com/pdf/%E6%98%87%E8%85%BE950%20NPU%E6%9E%B6%E6%9E%84%E7%99%BD%E7%9A%AE%E4%B9%A6.pdf" target="_blank" rel="noreferrer">950 白皮书 §3</a></td><td>训练与大模型推理，特别是解码（Decode）；也支持预填充。<a href="https://hifloat.gccorg.com/pdf/%E6%98%87%E8%85%BE950%20NPU%E6%9E%B6%E6%9E%84%E7%99%BD%E7%9A%AE%E4%B9%A6.pdf" target="_blank" rel="noreferrer">950 白皮书 §3</a></td></tr><tr><td>HBM 容量／带宽</td><td>HiBL 1.0；128 GB／1.6 TB/s 或 112 GB／1.4 TB/s。<a href="https://www.huawei.com/cn/news/2025/9/hc-xu-keynote-speech" target="_blank" rel="noreferrer">华为技术演讲</a>、<a href="https://hifloat.gccorg.com/pdf/%E6%98%87%E8%85%BE950%20NPU%E6%9E%B6%E6%9E%84%E7%99%BD%E7%9A%AE%E4%B9%A6.pdf" target="_blank" rel="noreferrer">950 白皮书表 3-1</a></td><td>HiZQ 2.0；144 GB 或 96 GB，带宽 4 TB/s。<a href="https://www.huawei.com/cn/news/2025/9/hc-xu-keynote-speech" target="_blank" rel="noreferrer">华为技术演讲</a>、<a href="https://hifloat.gccorg.com/pdf/%E6%98%87%E8%85%BE950%20NPU%E6%9E%B6%E6%9E%84%E7%99%BD%E7%9A%AE%E4%B9%A6.pdf" target="_blank" rel="noreferrer">950 白皮书表 3-1</a></td></tr><tr><td>FP16/BF16、FP8、MXFP4 峰值</td><td>最高分别为 486、919、1,784 TFLOPS。<a href="https://hifloat.gccorg.com/pdf/%E6%98%87%E8%85%BE950%20NPU%E6%9E%B6%E6%9E%84%E7%99%BD%E7%9A%AE%E4%B9%A6.pdf" target="_blank" rel="noreferrer">950 白皮书表 3-1</a></td><td>最高分别为 547、1,034、2,007 TFLOPS。<a href="https://hifloat.gccorg.com/pdf/%E6%98%87%E8%85%BE950%20NPU%E6%9E%B6%E6%9E%84%E7%99%BD%E7%9A%AE%E4%B9%A6.pdf" target="_blank" rel="noreferrer">950 白皮书表 3-1</a></td></tr><tr><td>代表产品</td><td>Atlas 350 加速卡、Atlas 850 超节点、Atlas 650 服务器。<a href="https://www.hiascend.com/document/detail/zh/Glossary/productform/hardwaredesc_0001.html" target="_blank" rel="noreferrer">昇腾产品形态说明</a></td><td>Atlas 850E 超节点、Atlas 650E 服务器、Atlas 950 SuperPoD 及 Flex。<a href="https://www.hiascend.com/document/detail/zh/Glossary/productform/hardwaredesc_0001.html" target="_blank" rel="noreferrer">昇腾产品形态说明</a></td></tr></tbody></table></div><p>上表算力为白皮书所列最高档的 <strong>Cube + Vector 理论总算力</strong>，不等于纯矩阵峰值、模型吞吐或所有量产卡的标称值。例如 Atlas 350 实际规格为 112 GB HBM、1.4 TB/s、1,561 TFLOPS MXFP4，采用 PCIe 5.0 ×16 和被动散热，整卡最大功耗不超过 600 W。对 950 的评估应使用同精度、同模型质量和同业务约束，不能用其 MXFP4 峰值直接对比 910C 的 FP16 峰值。<a href="https://hifloat.gccorg.com/pdf/%E6%98%87%E8%85%BE950%20NPU%E6%9E%B6%E6%9E%84%E7%99%BD%E7%9A%AE%E4%B9%A6.pdf" target="_blank" rel="noreferrer">昇腾 950 白皮书表 3-1</a>、<a href="https://www.hiascend.com/hardware/accelerator-card" target="_blank" rel="noreferrer">Atlas 350 加速卡</a></p><h3 id="atlas-950-superpod-不要混用路线图与产品规格" tabindex="-1">Atlas 950 SuperPoD：不要混用路线图与产品规格 <a class="header-anchor" href="#atlas-950-superpod-不要混用路线图与产品规格" aria-label="Permalink to “Atlas 950 SuperPoD：不要混用路线图与产品规格”">​</a></h3><ul><li><strong>8,192 卡是早期公布的满配目标</strong>：华为 2025 年技术演讲及 2026 年 MWC 材料介绍了最大 8,192 颗 950DT 的方案；不应把该数字写成当前产品页标准配置或已交付规模。<a href="https://www.huawei.com/cn/news/2025/9/hc-xu-keynote-speech" target="_blank" rel="noreferrer">2025 年技术演讲</a>、<a href="https://www.huawei.com/cn/news/2026/3/mwc-superpod-computing" target="_blank" rel="noreferrer">2026 年 MWC 发布资料</a></li><li><strong>1,024 卡是已经展示、并有公开技术规格的配置</strong>：华为在 2026 年 7 月展示 1,024 卡真机，9 月称昇腾 950 超节点已规模商用。昇腾社区中文产品页列出 64 或 1,024 卡配置；1,024 卡档最大配置为 1,024 颗 950DT 和 256 颗鲲鹏 950，标称最高 1 EFLOPS FP8、2 EFLOPS MXFP4，计算柜和灵衢互联柜均为液冷。<a href="https://www.huawei.com/cn/news/2026/7/atlas-950-superpod" target="_blank" rel="noreferrer">WAIC 真机报道</a>、<a href="https://www.huawei.com/cn/news/2026/9/hc-wang-keynote" target="_blank" rel="noreferrer">2026 年 9 月商用披露</a>、<a href="https://www.hiascend.com/hardware/cluster?tag=950" target="_blank" rel="noreferrer">Atlas 950 中文产品规格</a></li><li><strong>256 TB 是全局统一编址口径，不是 HBM 总量</strong>：同一产品页另列设备内存为 <strong>1,024 × 96 GB</strong>、最高 4 TB/s；不要将其替换成芯片级最高档的 144 GB，也不要用 256 TB 为模型计算本地 HBM 预算。<a href="https://www.hiascend.com/hardware/cluster?tag=950" target="_blank" rel="noreferrer">Atlas 950 中文产品规格</a>、<a href="https://hifloat.gccorg.com/pdf/%E6%98%87%E8%85%BE950%20NPU%E6%9E%B6%E6%9E%84%E7%99%BD%E7%9A%AE%E4%B9%A6.pdf" target="_blank" rel="noreferrer">950 白皮书表 3-1</a></li></ul><h2 id="选型、部署与验收" tabindex="-1">选型、部署与验收 <a class="header-anchor" href="#选型、部署与验收" aria-label="Permalink to “选型、部署与验收”">​</a></h2>`,9),(e(),l(i,null,{default:t(()=>[r(h,{id:`mermaid-355`,class:`mermaid`,graph:`flowchart%20LR%0A%20%20%20%20A%5B%22%E6%98%8E%E7%A1%AE%E6%A8%A1%E5%9E%8B%E3%80%81%E7%B2%BE%E5%BA%A6%E5%92%8C%E4%B8%9A%E5%8A%A1%E6%8C%87%E6%A0%87%22%5D%20--%3E%20B%5B%22%E4%BC%B0%E7%AE%97%20HBM%20%E4%B8%8E%E9%80%9A%E4%BF%A1%E9%9C%80%E6%B1%82%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E7%A1%AE%E5%AE%9A%E8%8A%AF%E7%89%87%E3%80%81%E6%95%B4%E6%9C%BA%E4%B8%8E%E4%BA%92%E8%81%94%E9%85%8D%E7%BD%AE%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E6%A0%B8%E5%AF%B9%E8%BD%AF%E4%BB%B6%E9%85%8D%E5%A5%97%E4%B8%8E%E6%9C%BA%E6%88%BF%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%E5%8D%95%E6%9C%BA%E9%AA%8C%E8%AF%81%20%E2%86%92%20%E5%A4%9A%E6%9C%BA%E5%8E%8B%E6%B5%8B%20%E2%86%92%20%E4%B8%9A%E5%8A%A1%E9%AA%8C%E6%94%B6%22%5D%0A`})]),fallback:t(()=>[...u[3]||=[o(` Loading... `,-1)]]),_:1})),u[8]||=s(`<p>图 4：建议的评估流程。先确定模型和业务约束，再用实机数据验证硬件方案；不以峰值算力或最大卡数替代验收。</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>检查项</th><th>建议记录或实测的内容</th></tr></thead><tbody><tr><td><strong>设备与软件配套</strong></td><td>确认整机型号、NPU 具体型号、HBM 配置、驱动、固件、CANN、框架插件和模型算子支持。Atlas A3 可用 <code>npu-smi info</code> 查看设备基本信息；安装 CANN 与 Python ACL 后可用 <code>python3 -c &quot;import acl;print(acl.get_soc_name())&quot;</code> 查询 SoC 型号。<a href="https://www.hiascend.com/document/detail/zh/HDK/2610/A3/A3npu/npusmia3_0009.html" target="_blank" rel="noreferrer">Atlas A3 npu-smi 命令参考</a>、<a href="https://www.hiascend.com/document/detail/zh/Glossary/productform/hardwaredesc_0001.html" target="_blank" rel="noreferrer">昇腾产品形态说明</a></td></tr><tr><td><strong>设备内存</strong></td><td>推理按权重、KV 缓存、运行时缓冲区和预留空间分别估算；训练还要计入激活、梯度、优化器状态等。以稠密 70B 模型为例，仅 BF16 权重即约 140 GB（70 × 10⁹ 参数、每参数 2 字节），已超过 128 GB 级单 NPU 的容量；仍需按实际分片或量化方案核算。</td></tr><tr><td><strong>通信与扩展</strong></td><td>分别实测单机、同超节点跨机、跨超节点三种路径；选择与目标并行方式相关的 AllReduce、AllGather、AlltoAll 等操作，记录消息大小、卡数、单向或双向口径及并发条件。昇腾通过 CANN 的 HCCL 提供这些集合通信能力。<a href="https://www.hiascend.com/document/detail/zh/CANNCommunityEdition/920beta2/commlib/hcclug/docs/zh/user_guide/hccl_intro.md" target="_blank" rel="noreferrer">HCCL 集合通信库</a></td></tr><tr><td><strong>业务性能</strong></td><td>训练记录同一模型、序列长度和精度下的稳定步时、吞吐及扩展效率；推理区分首 Token 时延（TTFT）、输出 Token 间隔、吞吐与尾延迟，并固定并发数、输入／输出长度和模型精度。启用低精度时同时比较模型质量。</td></tr><tr><td><strong>机房与运维</strong></td><td>核对机柜功率、供电制式与冗余、进风条件或液冷接口、网络布线与光模块配套。验收时留存温度、功耗、设备与链路健康信息，以及长时间负载下的告警和恢复结果。</td></tr></tbody></table></div><p>对 910C，优先比较目标 A3 整机的真实配置，再区分是单卡算力、HBM，还是跨卡通信限制了任务。对 950，先确认模型能否有效利用原生低精度，再决定是评估 950PR 的预填充／推荐吞吐，还是评估 950DT 的访存、解码及训练表现；混合负载应使用同一业务指标做端到端验证。<a href="https://e.huawei.com/cn/products/computing/ascend/atlas-800t-a3" target="_blank" rel="noreferrer">Atlas 800T A3</a>、<a href="https://hifloat.gccorg.com/pdf/%E6%98%87%E8%85%BE950%20NPU%E6%9E%B6%E6%9E%84%E7%99%BD%E7%9A%AE%E4%B9%A6.pdf" target="_blank" rel="noreferrer">昇腾 950 NPU 架构白皮书</a></p>`,3)])}var p=c(d,[[`render`,f]]);export{u as __pageData,p as default};